{
  "name": "context-meter",
  "version": "0.2.0",
  "description": "A band above the prompt with what fills the context window, by category, a countdown to when the prompt cache expires, and a Compact button",
  "author": {
    "name": "Chien Vu Minh"
  },
  "license": "MIT",
