      "type": "string",
      "title": "Prompt cache lifetime",
      "description": "auto: 1h on a Claude subscription, 5m with an API key (Claude Code's defaults; a mod cannot read the real setting). Pick 5m or 1h if you set promptCacheTtl or are drawing on usage credits.",
      "default": "auto",
      "options": [
        "auto",
        "5m",
        "1h"
      ]
    },
    "breakdown": {
      "type": "string",
      "title": "How the categories are counted",
      "description": "summary: estimated locally, no requests. full: counted with the token-count API after every turn, as /context does.",
      "default": "summary",
      "options": [
        "summary",
        "full"
      ]
    },
    "band": {
      "type": "string",
      "title": "Band above the prompt",
      "description": "off: the band stays hidden until you type /context-meter on, and /context-meter off hides it again. on: the band shows from the start. Either way the mod keeps working; this changes only what is drawn.",
      "default": "off",
      "options": [
        "off",
        "on"
      ]
    }
  }
}

